/// <summary>
/// This is a controller class
/// CB355_DutyRoll
/// </summary>
final class METDutyAdValorumClaimGenerateController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// This method creates new instances
/// </summary>
protected void new()
{
    super();
    this.parmClassName(classStr(METDutyAdValorumClaimGenerateService));
    this.parmMethodName(methodStr(METDutyAdValorumClaimGenerateService, processOperation));
}

    /// <summary>
    /// Initializes data contract.
    /// </summary>
    public void initContract()
    {
        METDutyRollMonthlyContract contract;

        contract = this.getDataContractObject() as METDutyRollMonthlyContract;

        if (contract)
        {
            METExciseDutyParameteres exciseDutyParameteres = METExciseDutyParameteres::Find();

            contract.parmThreadCount(exciseDutyParameteres.DutyAdValorumClaimtThreadCount);
        }
    }

/// <summary>
/// This is a construct method
/// </summary>
/// <returns>METDutyRollMonthlyController</returns>
public static METDutyAdValorumClaimGenerateController construct()
{
    return new METDutyAdValorumClaimGenerateController();
}

/// <summary>
/// Main method
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    METDutyAdValorumClaimGenerateController controller = new METDutyAdValorumClaimGenerateController();
    controller.parmArgs(_args);
    controller.initContract();
    controller.startOperation();
}

/// <summary>
/// The caption method of the batch job dialog.
/// </summary>
/// <returns>String value to be used on dialog</returns>
public ClassDescription caption()
{
    return "@MET:GenerateAdValorumClaim";
}
